function main() {
  const args = process.argv.slice(2);
  const flags = new Set(args.filter((a) => a.startsWith("--")));
  const positional = args.filter((a) => !a.startsWith("--"));

  const known = new Set(["--dry-run", "--list", "--force-config", "--help"]);
  for (const flag of flags) {
    if (!known.has(flag)) fail(`Unknown option ${flag}. Run with --help to see the options.`);
  }
  if (flags.has("--help")) {
    console.log(
      [
        "Usage: node generate-project.js [target-folder] [options]",
        "",
        "  --dry-run       Show what would be written. Change nothing.",
        "  --list          List the bundled files and exit.",
        "  --force-config  Also replace existing config files (old ones are backed up).",
        "  --help          Show this message.",
      ].join("\n"),
    );
    return;
  }
  if (positional.length > 1) fail("Give at most one target folder.");

  const files = loadBundle();

  if (flags.has("--list")) {
    for (const file of files) console.log(`${file.kind.padEnd(6)}  ${file.path}`);
    console.log(`\n${files.length} files`);
    return;
  }

  const dryRun = flags.has("--dry-run");
  const forceConfig = flags.has("--force-config");
  const target = path.resolve(positional[0] ?? ".");
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const backupRoot = path.join(target, ".steamgauge-backup", stamp);

  const counts = { created: 0, updated: 0, unchanged: 0, kept: 0 };
  const kept = [];
  let backedUp = false;

  console.log(`${dryRun ? "[dry run] " : ""}Target: ${target}\n`);

  // Pass 1: decide what to do with every file. Any problem stops the run
  // here, before a single file has been written.
  const plan = files.map((file) => {
    const destination = resolveInside(target, file.path);
    const existing = readIfFile(destination);

    let action;
    if (existing === null) action = "created";
    else if (sha256(existing) === file.sha256) action = "unchanged";
    else if (file.kind === "config" && !forceConfig) action = "kept";
    else action = "updated";

    return { file, destination, action };
  });

  // Pass 2: report, and unless this is a dry run, write.
  for (const { file, destination, action } of plan) {
    counts[action]++;
    if (action === "kept") kept.push(file.path);
    if (action !== "unchanged") console.log(`  ${label(action)}  ${file.path}`);

    if (dryRun || action === "unchanged" || action === "kept") continue;

    if (action === "updated") {
      const backup = resolveInside(backupRoot, file.path);
      fs.mkdirSync(path.dirname(backup), { recursive: true });
      fs.copyFileSync(destination, backup);
      backedUp = true;
    }
    fs.mkdirSync(path.dirname(destination), { recursive: true });
    fs.writeFileSync(destination, file.content, "utf8");
  }

  console.log(
    `\n${dryRun ? "Would have: " : ""}${counts.created} created, ${counts.updated} replaced, ` +
      `${counts.unchanged} already up to date, ${counts.kept} existing config kept.`,
  );
  if (backedUp) {
    console.log(`Previous versions of replaced files are in ${path.relative(target, backupRoot)}`);
  }
  if (kept.length > 0) {
    console.log(
      "\nThese config files already existed and were left as they are:\n" +
        kept.map((p) => `  ${p}`).join("\n") +
        "\nCompare them with the bundled versions (--force-config replaces them, with a backup).",
    );
  }
  if (!dryRun) {
    console.log(
      [
        "",
        "Next steps:",
        "  1. npm install",
        "  2. Copy .env.example to .env.local and fill in the values.",
        "  3. In the Supabase SQL Editor, run supabase/migrations/0001_steamlite_init.sql",
        "     and then 0002_price_history.sql (skip any you have already run).",
        "  4. npm run typecheck",
        "  5. npm run dev, then open http://localhost:3000 in Chrome or Firefox.",
      ].join("\n"),
    );
  }
}

/** Decodes the bundle and verifies every file against its recorded hash. */
function loadBundle() {
  let parsed;
  try {
    parsed = JSON.parse(zlib.gunzipSync(Buffer.from(BUNDLE, "base64")).toString("utf8"));
  } catch {
    fail("The bundled project data is damaged. Download generate-project.js again.");
  }
  const files = parsed.files;
  for (const file of files) {
    if (sha256(Buffer.from(file.content, "utf8")) !== file.sha256) {
      fail(`Bundled file ${file.path} failed its integrity check. Download the script again.`);
    }
  }
  return files;
}

/** Joins a bundled relative path onto a base folder and refuses anything that escapes it. */
function resolveInside(base, relativePath) {
  const resolved = path.resolve(base, ...relativePath.split("/"));
  const prefix = base.endsWith(path.sep) ? base : base + path.sep;
  if (path.isAbsolute(relativePath) || !resolved.startsWith(prefix)) {
    fail(`Refusing to write outside the target folder: ${relativePath}`);
  }
  return resolved;
}

/** The file's bytes, null if nothing is there. Stops if a folder is in the way. */
function readIfFile(file) {
  let stat;
  try {
    stat = fs.statSync(file);
  } catch (err) {
    if (err && (err.code === "ENOENT" || err.code === "ENOTDIR")) return null;
    throw err;
  }
  if (!stat.isFile()) fail(`${file} exists but is not a file. Move it out of the way and run again.`);
  return fs.readFileSync(file);
}

function sha256(data) {
  return crypto.createHash("sha256").update(data).digest("hex");
}

function label(action) {
  return { created: "create ", updated: "replace", kept: "keep   " }[action];
}

function fail(message) {
  console.error(`generate-project: ${message}`);
  process.exit(1);
}

main();
